using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Graph.StarForming;

internal sealed class WitnessBudgetDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Combinatorics/Graph/StarForming/WitnessBudget.";
    private static readonly LibraryNoteRef Source = LibraryNoteRef.Create("D5/L/Certificates/omega2026starformingfamily");
    private static DocumentBlock Node(string name, string title, string text, DescribeRole role) =>
        Describe.Lean(DescribeId.Create(name.Replace('_', '-').Replace('.', '-').ToLowerInvariant()), DeclarationHandle.Create(Prefix + name[(name.LastIndexOf('.') + 1)..]),
            H(title), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(Source),
            Blocks(Paragraph(Text(text))), role);

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Actual high-witness payments and regular equality resources", H("Actual high-witness payments and regular equality resources"),
        Blocks(Paragraph(Text("Actual injective deletion witnesses give an exact regular isolate-plus-unused budget. Tightness classifies omitted selected degrees as one, two or d. Every one-neighbor resource has a unique full-high owner; every two-neighbor resource has a unique adjacent degree d-minus-one high owner and an actual isolate as its other selected neighbor. Actual witness and leaf bijections give the corresponding class cardinalities. The high graph is d-minus-one regular under isolate-tight bipartite hypotheses, and under order equality without bipartiteness. Full resources have only selected nonhigh neighbors and selected leaves have only their support, private resource and full resources as neighbors. For every positive-degree finite regular bipartite graph, SF attains the order bound if and only if beta does. Complete converse partitions, all balance and component identities, path forms and Heawood block credits remain separate obligations.")),
            Node("payment_le_capacity", "payment le capacity", "Exact declaration: theorem payment_le_capacity (d : ℕ) (hdegree : ∀ v, degree G v ≤ d) (x : V) : payment G S hS x ≤ d-selectedDegree G S x.", DescribeRole.Theorem),
            Node("payment_sum", "payment sum", "Exact declaration: theorem payment_sum : ∑ x ∈ Finset.univ \\ S, payment G S hS x = ∑ v ∈ CertificateBound.high G S, (selectedDegree G S v-1).", DescribeRole.Theorem),
            Node("payment_add_unused", "payment add unused", "Exact declaration: theorem payment_add_unused (d : ℕ) (hdegree : ∀ v, degree G v ≤ d) (x : V) : payment G S hS x + unused G S hS d x = d-selectedDegree G S x.", DescribeRole.Theorem),
            Node("regular_budget", "regular budget", "Exact declaration: theorem regular_budget (d : ℕ) (hd : 1 ≤ d) (hdegree : ∀ v, degree G v=d) : (2*d-1)*S.card + (isolates G S).card + (∑ x ∈ Finset.univ \\ S, unused G S hS d x) = d*Fintype.card V.", DescribeRole.Theorem),
            Node("payment_at_witness", "payment at witness", "Exact declaration: theorem payment_at_witness (v : V) (hv : v ∈ CertificateBound.high G S) : payment G S hS (BipartiteExchange.witness G S hS v) = selectedDegree G S v-1.", DescribeRole.Theorem),
            Node("payment_off_image", "payment off image", "Exact declaration: theorem payment_off_image (x : V) (hx : ¬ ∃ v ∈ CertificateBound.high G S, BipartiteExchange.witness G S hS v=x) : payment G S hS x=0.", DescribeRole.Theorem),
            Node("tight_iff_pointwise", "tight iff pointwise", "Exact declaration: theorem tight_iff_pointwise (d : ℕ) (hd : 1 ≤ d) (hdegree : ∀ v, degree G v=d) : (2*d-1)*S.card+(isolates G S).card=d*Fintype.card V ↔ ∀ x ∈ Finset.univ \\ S, unused G S hS d x=0.", DescribeRole.Theorem),
            Node("tight_outside_classes", "tight outside classes", "Exact declaration: theorem tight_outside_classes (d : ℕ) (hd : 1 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card+(isolates G S).card=d*Fintype.card V) : (∀ v ∈ CertificateBound.high G S, selectedDegree G S v+selectedDegree G S (BipartiteExchange.witness G S hS v)=d+1) ∧ (∀ x ∈ Finset.univ \\ S, (∃ v ∈ CertificateBound.high G S, BipartiteExchange.witness G S hS v=x) ∨ selectedDegree G S x=d).", DescribeRole.Theorem),
            Node("tight_witness_classes", "tight witness classes", "Exact declaration: theorem tight_witness_classes (d : ℕ) (hd : 1 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card+(isolates G S).card=d*Fintype.card V) (v : V) (hv : v ∈ CertificateBound.high G S) : let x.", DescribeRole.Theorem),
            Node("tight_no_extra", "tight no extra", "Exact declaration: theorem tight_no_extra (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (d : ℕ) (hd : 3 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card+(isolates G S).card=d*Fintype.card V) (u : V) : ¬ BipartiteExchange.Extra G S hS u.", DescribeRole.Theorem),
            Node("tight_leaf_reserved", "tight leaf reserved", "Exact declaration: theorem tight_leaf_reserved (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (d : ℕ) (hd : 3 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card+(isolates G S).card=d*Fintype.card V) (u h : V) (hu : BipartiteExchange.LeafAt G S u h) : BipartiteExchange.Reserved G S hS u.", DescribeRole.Theorem),
            Node("tight_leaf_full", "tight leaf full", "Exact declaration: theorem tight_leaf_full (hS : IsMinimalStarForming G 2 S) (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (d : ℕ) (hd : 3 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card+(isolates G S).card=d*Fintype.card V) (u h : V) (hu : BipartiteExchange.LeafAt G S u h) : selectedDegree G S h=d.", DescribeRole.Theorem),
            Node("tight_full_unique_leaf", "tight full unique leaf", "Exact declaration: theorem tight_full_unique_leaf (hS : IsMinimalStarForming G 2 S) (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (d : ℕ) (hd : 3 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card+(isolates G S).card=d*Fintype.card V) (v : V) (hv : v ∈ CertificateBound.high G S) (hfull : selectedDegree G S v=d) : ∃! u, BipartiteExchange.LeafAt G S u v.", DescribeRole.Theorem),
            Node("tight_high_regular", "tight high regular", "Exact declaration: theorem tight_high_regular (hS : IsMinimalStarForming G 2 S) (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (d : ℕ) (hd : 3 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card+(isolates G S).card=d*Fintype.card V) (v : V) (hv : v ∈ CertificateBound.high G S) : selectedDegree G (CertificateBound.high G S) v=d-1.", DescribeRole.Theorem),
            Node("order_tight_isolates", "order tight isolates", "Exact declaration: theorem order_tight_isolates (hS : IsMinimalStarForming G 2 S) (d : ℕ) (hd : 1 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card=d*Fintype.card V) : (isolates G S).card=0.", DescribeRole.Theorem),
            Node("order_tight_leaf_witness", "order tight leaf witness", "Exact declaration: theorem order_tight_leaf_witness (hS : IsMinimalStarForming G 2 S) (d : ℕ) (hd : 2 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card=d*Fintype.card V) (u h : V) (hu : BipartiteExchange.LeafAt G S u h) : G.Adj (BipartiteExchange.witness G S hS h) u ∧ selectedDegree G S h=d.", DescribeRole.Theorem),
            Node("order_tight_high_full", "order tight high full", "Exact declaration: theorem order_tight_high_full (hS : IsMinimalStarForming G 2 S) (d : ℕ) (hd : 2 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card=d*Fintype.card V) (v : V) (hv : v ∈ CertificateBound.high G S) : selectedDegree G S v=d.", DescribeRole.Theorem),
            Node("order_tight_unique_leaf", "order tight unique leaf", "Exact declaration: theorem order_tight_unique_leaf (hS : IsMinimalStarForming G 2 S) (d : ℕ) (hd : 2 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card=d*Fintype.card V) (v : V) (hv : v ∈ CertificateBound.high G S) : ∃! u, BipartiteExchange.LeafAt G S u v.", DescribeRole.Theorem),
            Node("tight_resource_degrees", "tight resource degrees", "Exact declaration: theorem tight_resource_degrees (hS : IsMinimalStarForming G 2 S) (d : ℕ) (hd : 3 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card+(isolates G S).card=d*Fintype.card V) (x : V) (hx : x ∉ S) : selectedDegree G S x=1 ∨ selectedDegree G S x=2 ∨ selectedDegree G S x=d.", DescribeRole.Theorem),
            Node("tight_one_owner", "tight one owner", "Exact declaration: theorem tight_one_owner (d : ℕ) (hd : 3 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card+(isolates G S).card=d*Fintype.card V) (x : V) (hx : x ∉ S) (hone : selectedDegree G S x=1) : ∃! v, v ∈ CertificateBound.high G S ∧ selectedDegree G S v=d ∧ BipartiteExchange.witness G S hS v=x.", DescribeRole.Theorem),
            Node("tight_two_owner", "tight two owner", "Exact declaration: theorem tight_two_owner (d : ℕ) (hd : 3 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card+(isolates G S).card=d*Fintype.card V) (x : V) (hx : x ∉ S) (htwo : selectedDegree G S x=2) : ∃! v, v ∈ CertificateBound.high G S ∧ selectedDegree G S v=d-1 ∧ BipartiteExchange.witness G S hS v=x ∧ G.Adj x v.", DescribeRole.Theorem),
            Node("tight_two_isolate", "tight two isolate", "Exact declaration: theorem tight_two_isolate (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (d : ℕ) (hd : 3 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card+(isolates G S).card=d*Fintype.card V) (x : V) (hx : x ∉ S) (htwo : selectedDegree G S x=2) : ∃ v u, v ∈ CertificateBound.high G S ∧ selectedDegree G S v=d-1 ∧ BipartiteExchange.witness G S hS v=x ∧ S.filter (G.Adj x)={v,u} ∧ BipartiteExchange.Isolate G S u.", DescribeRole.Theorem),
            Node("tight_resource_cardinalities", "tight resource cardinalities", "Exact declaration: theorem tight_resource_cardinalities (hS : IsMinimalStarForming G 2 S) (d : ℕ) (hd : 3 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card+(isolates G S).card=d*Fintype.card V) : ((CertificateBound.high G S).filter (fun v => selectedDegree G S v=d)).card = ((Finset.univ \\ S).filter (fun x => selectedDegree G S x=1)).card ∧ ((CertificateBound.high G S).filter (fun v => selectedDegree G S v=d-1)).card = ((Finset.univ \\ S).filter (fun x => selectedDegree G S x=2)).card.", DescribeRole.Theorem),
            Node("tight_leaf_cardinality", "tight leaf cardinality", "Exact declaration: theorem tight_leaf_cardinality (hS : IsMinimalStarForming G 2 S) (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (d : ℕ) (hd : 3 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card+(isolates G S).card=d*Fintype.card V) : ((CertificateBound.high G S).filter (fun v => selectedDegree G S v=d)).card = (S.filter (fun u => ∃ v, BipartiteExchange.LeafAt G S u v)).card.", DescribeRole.Theorem),
            Node("order_tight_high_regular", "order tight high regular", "Exact declaration: theorem order_tight_high_regular (hS : IsMinimalStarForming G 2 S) (d : ℕ) (hd : 2 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card=d*Fintype.card V) (v : V) (hv : v ∈ CertificateBound.high G S) : selectedDegree G (CertificateBound.high G S) v=d-1.", DescribeRole.Theorem),
            Node("tight_high_outside", "tight high outside", "Exact declaration: theorem tight_high_outside (d : ℕ) (hd : 3 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card+(isolates G S).card=d*Fintype.card V) (v x : V) (hv : v ∈ CertificateBound.high G S) (hx : x ∉ S) (hvx : G.Adj v x) : selectedDegree G S v=d-1 ∧ BipartiteExchange.witness G S hS v=x ∧ selectedDegree G S x=2.", DescribeRole.Theorem),
            Node("tight_full_resource_neighbors", "tight full resource neighbors", "Exact declaration: theorem tight_full_resource_neighbors (hS : IsMinimalStarForming G 2 S) (d : ℕ) (hd : 3 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card+(isolates G S).card=d*Fintype.card V) (y : V) (hy : y ∉ S) (hyd : selectedDegree G S y=d) (v : V) (hyv : G.Adj y v) : v ∈ S ∧ v ∉ CertificateBound.high G S.", DescribeRole.Theorem),
            Node("tight_leaf_remaining_neighbors", "tight leaf remaining neighbors", "Exact declaration: theorem tight_leaf_remaining_neighbors (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (d : ℕ) (hd : 3 ≤ d) (hdegree : ∀ v, degree G v=d) (ht : (2*d-1)*S.card+(isolates G S).card=d*Fintype.card V) (u v : V) (hu : BipartiteExchange.LeafAt G S u v) (x : V) (hux : G.Adj u x) (hxv : x≠v) (hxw : x≠BipartiteExchange.witness G S hS v) : x ∉ S ∧ selectedDegree G S x=d.", DescribeRole.Theorem),
            Node("order_endpoint_iff", "order endpoint iff", "Exact declaration: theorem order_endpoint_iff (hG : G.Colorable 2) (d : ℕ) (hd : 1 ≤ d) (hdegree : ∀ v, degree G v=d) : (2*d-1)*SF G 2=d*Fintype.card V ↔ (2*d-1)*beta G 2=d*Fintype.card V.", DescribeRole.Theorem)), []));
}
